
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_xc_hcth_p14_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_xc_hcth_p14", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.425406930980801e+00, -4.338190001267257e+00, -4.216034096099301e+00, -4.046946114901197e+00, -3.816846950379278e+00, -3.511360328100786e+00, -3.120153061448249e+00, -2.645276324472377e+00, -2.113712559391798e+00, -1.581957220959815e+00, -1.090842907098299e+00, -7.952740745889468e-01, -6.933612378685013e-01, -5.694336782998085e-01, -4.152943063168150e-01, -2.716056635623439e-01, -1.560119898445963e-01, -6.347377949700034e-02, -1.557775463588284e-02, -1.949307163067024e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


